Archive Payload As JSON.code:
// Archive the incoming payload to S3 as JSON.
put({
  bucket: $.configuration.bucket, // optional: defaults to the credential's bucket
  key: `submissions/${new Date().toISOString().slice(0, 10)}/${$.data.id}.json`,
  body: JSON.stringify($.data),
  contentType: 'application/json',
});

Upload CSV Export.code:
// Build a CSV from rows and upload it to S3.
put({
  key: `exports/payments-${new Date().toISOString().slice(0, 10)}.csv`,
  body: [
    'beneficiary_id,name,amount,currency',
    ...$.data.payments.map(p => `${p.beneficiaryId},${p.name},${p.amount},${p.currency}`),
  ].join('\n'),
  contentType: 'text/csv',
});

Upload Encrypted File.code:
// Upload a sensitive file with server-side encryption.
put({
  key: `lab-results/${$.data.facilityCode}/${$.data.fileName}`,
  body: Buffer.from($.data.fileBase64, 'base64'), // decode an attachment
  contentType: $.data.mimeType, // e.g. 'application/pdf'
  serverSideEncryption: 'AES256', // or 'aws:kms'
});

Archive Each Record Separately.code:
// Write one object per record.
each(
  $.data.patients,
  put({
    key: `patients/${$.data.patientId}.json`,
    body: JSON.stringify($.data),
    contentType: 'application/json',
  })
);

List Files In Folder.code:
// List objects under a prefix.
list({
  bucket: $.configuration.bucket, // optional: defaults to the credential's bucket
  prefix: 'incoming/2026-11/',
  maxKeys: 100,
});

Find New Files Since Last Run.code:
// List a drop folder, then keep files newer than the last run.
list({ prefix: 'incoming/' });
fn(state => {
  const since = new Date(state.lastRunAt || 0);
  state.newFiles = state.data.filter(obj => new Date(obj.LastModified) > since);
  state.lastRunAt = new Date().toISOString();
  return state;
});

Read JSON File.code:
// Download and parse a JSON file.
get({
  key: `config/facility-mappings.json`,
});

Download Binary File.code:
// Download a file. Non-JSON content (CSV, PDF, image) is returned
// base64-encoded, with its contentType and contentLength.
get({
  bucket: $.configuration.bucket, // optional: defaults to the credential's bucket
  key: $.data.key, // e.g. 'incoming/2026-11/enrolment.csv'
});
